-- 0073 (post_match idempotency key) — POSTCHECK. READ ONLY. Every row must be ok = true.
-- On staging: Staging database workflow, action m3_0073_postcheck.
with checks(item, ok, detail) as (
  select 'post_match: exactly one, the 0073 version (with p_token)', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '6a8feb9a5b8c59e81d8d72ac49076635' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), 'missing')
  union all select 'post_match takes p_token last, default null (the website''s ten named arguments still resolve)', (select pg_get_function_arguments(oid) like '%p_join_mode text DEFAULT ''open''::text, p_token uuid DEFAULT NULL::uuid' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), (select pg_get_function_arguments(oid) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match')
  union all select 'post_match: signed-in users and the service role only', has_function_privilege('authenticated', 'post_match(uuid,sport,timestamptz,timestamptz,int,int,int,text,uuid,text,uuid)', 'execute') and has_function_privilege('service_role', 'post_match(uuid,sport,timestamptz,timestamptz,int,int,int,text,uuid,text,uuid)', 'execute') and not has_function_privilege('anon', 'post_match(uuid,sport,timestamptz,timestamptz,int,int,int,text,uuid,text,uuid)', 'execute'), ''
  union all select 'matches.client_token and its unique index per organiser', exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'matches' and column_name = 'client_token') and exists (select 1 from pg_indexes where indexname = 'matches_organizer_client_token' and indexdef like '%UNIQUE%(organizer_id, client_token)%'), ''
)
select item, ok, detail from checks order by item;
